/**
 * @file Column helpers shared by the app's tables (not Better Auth's, which
 * are generated).
 */
import { sql } from 'drizzle-orm';
import { type AnyPgColumn, check, timestamp, uuid } from 'drizzle-orm/pg-core';

/**
 * Primary key column: a UUIDv7 generated by Postgres. Time-ordered, so new
 * rows append to the index.
 *
 * @returns The column definition.
 */
export const id = () =>
  uuid('id')
    .primaryKey()
    .default(sql`uuidv7()`);

/**
 * Timestamp column with time zone.
 *
 * @param name - The column name.
 * @returns The column definition.
 */
export const timestampTz = (name: string) => timestamp(name, { withTimezone: true });

/**
 * Creation time column, set by the database.
 *
 * @returns The column definition.
 */
export const createdAt = () => timestampTz('created_at').defaultNow().notNull();

/**
 * A CHECK constraint that keeps a text column to a fixed list of values,
 * written out from the same list its TypeScript type is built from, so a
 * value added to the list makes `pnpm db:generate` update the check. A null
 * passes, as it does for any CHECK, so an optional column stays optional.
 *
 * @param name - The constraint's name, `<table>_<column>_valid`.
 * @param column - The column.
 * @param values - The values it may hold.
 * @returns The constraint.
 */
export const oneOf = (name: string, column: AnyPgColumn, values: readonly string[]) =>
  check(
    name,
    sql`${column} in (${sql.raw(values.map((value) => `'${value.replaceAll("'", "''")}'`).join(', '))})`,
  );
